-- D-33: indexes for the graph walk. Generated by drizzle-kit from
-- src/schema/entities.ts and src/schema/evidence.ts. Forward-only and additive.
-- The graph store now walks each relationship both ways (as the person probe
-- does), so it steps from a relationship's target as often as from its source.
-- The unique key (tenant_id, source_entity_id, target_entity_id, kind) serves
-- the source side, and this serves the target side. It also counts each
-- returned edge's claims by relationship.
-- Built as plain CREATE INDEX, like every index migration here: the migrator
-- runs in a transaction, where CONCURRENTLY is not allowed. Writes to the two
-- tables wait while each index builds; the build time at the measured size is
-- recorded in docs/PLAN.md, D-33.
CREATE INDEX "claims_relationship_idx" ON "claims" USING btree ("tenant_id","relationship_id");--> statement-breakpoint
CREATE INDEX "entity_relationships_target_idx" ON "entity_relationships" USING btree ("tenant_id","target_entity_id");